repo_files.ring_stream.py:
"""Streaming circular telemetry buffer."""

from typing import Any, List
from buffer import CircularBuffer


class RingStreamLogger:
    def __init__(self, capacity: int = 3):
        self.buffer = CircularBuffer(capacity=capacity)

    def log_event(self, event_name: str) -> None:
        self.buffer.write(event_name)

    def drain_all(self) -> List[str]:
        items: list[str] = []
        while True:
            val = self.buffer.read()
            if val is None:
                break
            items.append(val)
        return items

repo_files.consumer.py:
"""Metrics consumer draining logger stream."""

from typing import List
from ring_stream import RingStreamLogger


class StreamConsumer:
    def __init__(self, logger: RingStreamLogger):
        self.logger = logger

    def consume_latest_batch(self) -> List[str]:
        return self.logger.drain_all()
